import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, afterEach } from "vitest";
import { ApiKeysRoute } from "../../src/routes/ApiKeysRoute";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

afterEach(() => vi.restoreAllMocks());

const SAMPLE_KEY = {
  id: "k1",
  name: "CI",
  token_prefix: "omck_",
  last_four: "1a2b",
  access_level: "read_only",
  status: "active",
  created_by_email: "a@e.com",
  created_at: "2026-06-01T00:00:00Z",
  expires_at: null,
  last_used_at: null,
  revoked_at: null,
};

function mockList(keys: unknown[], status = 200): void {
  globalThis.fetch = vi.fn(
    async () =>
      new Response(JSON.stringify({ data: { api_keys: keys } }), {
        status,
        headers: { "Content-Type": "application/json" },
      }),
  ) as unknown as typeof fetch;
}

describe("ApiKeysRoute", () => {
  it("shows loading state before data arrives", () => {
    let resolveFetch!: () => void;
    globalThis.fetch = vi.fn(async () => {
      await new Promise<void>((r) => { resolveFetch = r; });
      return new Response(JSON.stringify({ data: { api_keys: [] } }), { status: 200 });
    }) as unknown as typeof fetch;
    render(<ApiKeysRoute />);
    expect(screen.getByRole("status")).toBeInTheDocument();
    resolveFetch();
  });

  it("shows empty state when no keys", async () => {
    mockList([]);
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-empty")).toBeInTheDocument(),
    );
  });

  it("renders a key row when present", async () => {
    mockList([SAMPLE_KEY]);
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
  });

  it("opens the create modal from the CTA", async () => {
    mockList([]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-create-cta")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-create-cta"));
    expect(screen.getByTestId("apikey-name")).toBeInTheDocument();
  });

  it("shows error state on load failure", async () => {
    mockList([], 500);
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(
        screen.getByText(m.admin_apikey_load_failed()),
      ).toBeInTheDocument(),
    );
  });

  it("opens the rotate confirm modal when clicking Rotate on a key row", async () => {
    mockList([SAMPLE_KEY]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-rotate"));
    expect(
      screen.getByText(m.admin_apikey_rotate_title()),
    ).toBeInTheDocument();
  });

  it("opens the revoke confirm modal when clicking Revoke on a key row", async () => {
    mockList([SAMPLE_KEY]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-revoke"));
    expect(
      screen.getByText(m.admin_apikey_revoke_title()),
    ).toBeInTheDocument();
  });

  it("completes rotate flow: confirm → secret reveal → reload", async () => {
    // First list call returns the key; then rotate returns secret; then reload call
    let callCount = 0;
    globalThis.fetch = vi.fn(async (url: unknown) => {
      const urlStr = String(url);
      if (urlStr.includes("/rotate")) {
        return new Response(
          JSON.stringify({
            data: {
              key: SAMPLE_KEY,
              secret: "omck_rotated_secret",
            },
          }),
          { status: 200, headers: { "Content-Type": "application/json" } },
        );
      }
      callCount++;
      return new Response(
        JSON.stringify({ data: { api_keys: callCount === 1 ? [SAMPLE_KEY] : [] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    // Open rotate modal
    await user.click(screen.getByTestId("apikey-rotate"));
    // Confirm rotate
    await user.click(screen.getByTestId("apikey-rotate-confirm"));
    // Secret reveal modal should appear
    await waitFor(() =>
      expect(screen.getByText(m.admin_apikey_secret_rotate_title())).toBeInTheDocument(),
    );
  });

  it("shows action error alert when rotate fails", async () => {
    globalThis.fetch = vi.fn(async (url: unknown) => {
      const urlStr = String(url);
      if (urlStr.includes("/rotate")) {
        return new Response(
          JSON.stringify({ error: { message: "rotate failed" } }),
          { status: 500, headers: { "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({ data: { api_keys: [SAMPLE_KEY] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-rotate"));
    await user.click(screen.getByTestId("apikey-rotate-confirm"));
    await waitFor(() =>
      expect(screen.getByTestId("apikey-action-error")).toBeInTheDocument(),
    );
  });

  it("completes revoke flow: confirm → reload", async () => {
    let callCount = 0;
    globalThis.fetch = vi.fn(async (url: unknown) => {
      const urlStr = String(url);
      if (urlStr.includes("/revoke")) {
        return new Response(null, { status: 204 });
      }
      callCount++;
      return new Response(
        JSON.stringify({ data: { api_keys: callCount === 1 ? [SAMPLE_KEY] : [] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-revoke"));
    await user.click(screen.getByTestId("apikey-revoke-confirm"));
    // After revoke + reload the empty state appears
    await waitFor(() =>
      expect(screen.getByTestId("apikey-empty")).toBeInTheDocument(),
    );
  });

  it("shows action error alert when revoke fails", async () => {
    globalThis.fetch = vi.fn(async (url: unknown) => {
      const urlStr = String(url);
      if (urlStr.includes("/revoke")) {
        return new Response(
          JSON.stringify({ error: { message: "revoke failed" } }),
          { status: 500, headers: { "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({ data: { api_keys: [SAMPLE_KEY] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-revoke"));
    await user.click(screen.getByTestId("apikey-revoke-confirm"));
    await waitFor(() =>
      expect(screen.getByTestId("apikey-action-error")).toBeInTheDocument(),
    );
  });

  it("completes the full create flow: issue → onIssued → secret reveal", async () => {
    // list GET → empty; POST issue → secret; reload GET → empty
    globalThis.fetch = vi.fn(async (_url: unknown, init?: RequestInit) => {
      if (init?.method === "POST") {
        return new Response(
          JSON.stringify({
            data: {
              key: SAMPLE_KEY,
              secret: "omck_brand_new_secret",
            },
          }),
          { status: 201, headers: { "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({ data: { api_keys: [] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-empty")).toBeInTheDocument(),
    );
    // Open create modal
    await user.click(screen.getByTestId("apikey-create-cta"));
    await user.type(screen.getByTestId("apikey-name"), "My Key");
    await user.click(screen.getByTestId("apikey-create-submit"));
    // Secret reveal modal should appear
    await waitFor(() =>
      expect(screen.getByText(m.admin_apikey_secret_reveal_title())).toBeInTheDocument(),
    );
  });

  it("closes the create modal via its cancel/close button", async () => {
    mockList([]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-create-cta")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-create-cta"));
    expect(screen.getByTestId("apikey-name")).toBeInTheDocument();
    // Press Escape to close
    await user.keyboard("{Escape}");
    await waitFor(() =>
      expect(screen.queryByTestId("apikey-name")).not.toBeInTheDocument(),
    );
  });

  it("closes the secret reveal modal after acking the checkbox", async () => {
    // Get to the reveal state by doing a rotate
    globalThis.fetch = vi.fn(async (url: unknown) => {
      const urlStr = String(url);
      if (urlStr.includes("/rotate")) {
        return new Response(
          JSON.stringify({ data: { key: SAMPLE_KEY, secret: "new_secret" } }),
          { status: 200, headers: { "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({ data: { api_keys: [SAMPLE_KEY] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }) as unknown as typeof fetch;

    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-rotate"));
    await user.click(screen.getByTestId("apikey-rotate-confirm"));
    await waitFor(() =>
      expect(screen.getByText(m.admin_apikey_secret_rotate_title())).toBeInTheDocument(),
    );
    // Ack the checkbox to unlock the Done button
    await user.click(screen.getByRole("checkbox"));
    // Close the reveal modal
    await user.click(screen.getByTestId("apikey-secret-done"));
    await waitFor(() =>
      expect(screen.queryByText(m.admin_apikey_secret_rotate_title())).not.toBeInTheDocument(),
    );
  });

  it("closes the rotate modal via its cancel button", async () => {
    mockList([SAMPLE_KEY]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-rotate"));
    expect(
      screen.getByText(m.admin_apikey_rotate_title()),
    ).toBeInTheDocument();
    await user.click(
      screen.getByRole("button", { name: m.admin_apikey_rotate_cancel() }),
    );
    await waitFor(() =>
      expect(
        screen.queryByText(m.admin_apikey_rotate_title()),
      ).not.toBeInTheDocument(),
    );
  });

  it("closes the revoke modal via its cancel button", async () => {
    mockList([SAMPLE_KEY]);
    const user = userEvent.setup();
    render(<ApiKeysRoute />);
    await waitFor(() =>
      expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument(),
    );
    await user.click(screen.getByTestId("apikey-revoke"));
    expect(
      screen.getByText(m.admin_apikey_revoke_title()),
    ).toBeInTheDocument();
    await user.click(
      screen.getByRole("button", { name: m.admin_apikey_revoke_cancel() }),
    );
    await waitFor(() =>
      expect(
        screen.queryByText(m.admin_apikey_revoke_title()),
      ).not.toBeInTheDocument(),
    );
  });
});


