import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi } from "vitest";
import { ApiKeysTable } from "../../src/apikeys/ApiKeysTable";
import type { ApiKey } from "../../src/api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

const key: ApiKey = {
  id: "k1",
  name: "CI",
  token_prefix: "omck_",
  last_four: "1a2b",
  access_level: "read_write",
  status: "active",
  created_by_email: "a@example.com",
  created_at: "2026-06-01T00:00:00Z",
  expires_at: null,
  last_used_at: null,
  revoked_at: null,
};

describe("ApiKeysTable", () => {
  it("renders a row with masked key + Never used + actions", () => {
    render(<ApiKeysTable keys={[key]} onRotate={vi.fn()} onRevoke={vi.fn()} />);
    expect(screen.getByTestId("apikey-row-k1")).toBeInTheDocument();
    expect(screen.getByText(/omck_/)).toHaveTextContent("1a2b");
    expect(
      screen.getByText(m.admin_apikey_last_used_never()),
    ).toBeInTheDocument();
  });

  it("fires onRevoke with the key", async () => {
    const onRevoke = vi.fn();
    const user = userEvent.setup();
    render(
      <ApiKeysTable keys={[key]} onRotate={vi.fn()} onRevoke={onRevoke} />,
    );
    await user.click(screen.getByTestId("apikey-revoke"));
    expect(onRevoke).toHaveBeenCalledWith(key);
  });

  it("fires onRotate with the key", async () => {
    const onRotate = vi.fn();
    const user = userEvent.setup();
    render(
      <ApiKeysTable keys={[key]} onRotate={onRotate} onRevoke={vi.fn()} />,
    );
    await user.click(screen.getByTestId("apikey-rotate"));
    expect(onRotate).toHaveBeenCalledWith(key);
  });
});


