import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, afterEach } from "vitest";
import { CreateApiKeyModal } from "../../src/apikeys/CreateApiKeyModal";

afterEach(() => vi.restoreAllMocks());

describe("CreateApiKeyModal", () => {
  it("issues a key and surfaces the secret via onIssued", async () => {
    globalThis.fetch = vi.fn(async () =>
      new Response(JSON.stringify({ data: { key: { id: "k1", name: "ci" }, secret: "omck_xyz" } }),
        { status: 201, headers: { "Content-Type": "application/json" } }),
    ) as unknown as typeof fetch;
    const onIssued = vi.fn();
    const user = userEvent.setup();
    render(<CreateApiKeyModal open onIssued={onIssued} onClose={vi.fn()} />);
    await user.type(screen.getByTestId("apikey-name"), "ci");
    await user.click(screen.getByTestId("apikey-create-submit"));
    await waitFor(() => expect(onIssued).toHaveBeenCalledWith("omck_xyz"));
  });
  it("blocks submit on empty name (no fetch)", async () => {
    const spy = vi.fn();
    globalThis.fetch = spy as unknown as typeof fetch;
    const user = userEvent.setup();
    render(<CreateApiKeyModal open onIssued={vi.fn()} onClose={vi.fn()} />);
    await user.click(screen.getByTestId("apikey-create-submit"));
    expect(spy).not.toHaveBeenCalled();
  });
});


