import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, afterEach } from "vitest";
import { RevokeApiKeyModal } from "../../src/apikeys/RevokeApiKeyModal";
import type { ApiKey } from "../../src/api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

afterEach(() => vi.restoreAllMocks());

const MOCK_KEY: ApiKey = {
  id: "k1",
  name: "CI Key",
  token_prefix: "omck_",
  last_four: "1a2b",
  access_level: "read_only",
  status: "active",
  created_by_email: "ci@example.com",
  created_at: "2026-06-01T00:00:00Z",
  expires_at: null,
  last_used_at: null,
  revoked_at: null,
};

describe("RevokeApiKeyModal", () => {
  it("renders nothing when apiKey is null", () => {
    render(
      <RevokeApiKeyModal
        open
        apiKey={null}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    expect(screen.queryByTestId("apikey-revoke-body")).not.toBeInTheDocument();
  });

  it("renders the modal title when open with a key", () => {
    render(
      <RevokeApiKeyModal
        open
        apiKey={MOCK_KEY}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    expect(
      screen.getByText(m.admin_apikey_revoke_title()),
    ).toBeInTheDocument();
  });

  it("renders the masked key in the body", () => {
    render(
      <RevokeApiKeyModal
        open
        apiKey={MOCK_KEY}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    const body = screen.getByTestId("apikey-revoke-body");
    // masked key is token_prefix + •••• + last_four
    expect(body).toHaveTextContent(/omck_/);
    expect(body).toHaveTextContent(/1a2b/);
  });

  it("calls onConfirm when the confirm button is clicked", async () => {
    const user = userEvent.setup();
    const onConfirm = vi.fn();
    render(
      <RevokeApiKeyModal
        open
        apiKey={MOCK_KEY}
        onConfirm={onConfirm}
        onClose={vi.fn()}
      />,
    );
    await user.click(screen.getByTestId("apikey-revoke-confirm"));
    expect(onConfirm).toHaveBeenCalledTimes(1);
  });

  it("calls onClose when the cancel button is clicked", async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();
    render(
      <RevokeApiKeyModal
        open
        apiKey={MOCK_KEY}
        onConfirm={vi.fn()}
        onClose={onClose}
      />,
    );
    await user.click(
      screen.getByRole("button", { name: m.admin_apikey_revoke_cancel() }),
    );
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("does not render when open=false", () => {
    render(
      <RevokeApiKeyModal
        open={false}
        apiKey={MOCK_KEY}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    // Modal is closed: title should not be visible in the DOM
    expect(
      screen.queryByTestId("apikey-revoke-body"),
    ).not.toBeInTheDocument();
  });
});


