import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, afterEach } from "vitest";
import { RotateApiKeyModal } from "../../src/apikeys/RotateApiKeyModal";
import type { ApiKey } from "../../src/api/apiKeys";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

afterEach(() => vi.restoreAllMocks());

const MOCK_KEY: ApiKey = {
  id: "k1",
  name: "Prod Key",
  token_prefix: "omck_",
  last_four: "9z8y",
  access_level: "read_write",
  status: "active",
  created_by_email: "admin@example.com",
  created_at: "2026-06-01T00:00:00Z",
  expires_at: null,
  last_used_at: null,
  revoked_at: null,
};

describe("RotateApiKeyModal", () => {
  it("renders nothing when apiKey is null", () => {
    render(
      <RotateApiKeyModal
        open
        apiKey={null}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    expect(screen.queryByTestId("apikey-rotate-body")).not.toBeInTheDocument();
  });

  it("renders the modal title when open with a key", () => {
    render(
      <RotateApiKeyModal
        open
        apiKey={MOCK_KEY}
        onConfirm={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    expect(
      screen.getByText(m.admin_apikey_rotate_title()),
    ).toBeInTheDocument();
  });

  it("renders the key name in the body", () => {
    render(
      <RotateApiKeyModal
        open
