import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, beforeEach } from "vitest";
import { SecretRevealModal } from "../../src/apikeys/SecretRevealModal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

beforeEach(() => {
  Object.assign(navigator, { clipboard: { writeText: vi.fn().mockResolvedValue(undefined) } });
});

describe("SecretRevealModal", () => {
  it("shows the secret once with a copy affordance and warning", () => {
    render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={vi.fn()} />);
    expect(screen.getByTestId("apikey-secret-value")).toHaveTextContent("omck_abc123");
    expect(screen.getByText(m.admin_apikey_secret_warning())).toBeInTheDocument();
  });
  it("Done is disabled until copy or ack", async () => {
    const user = userEvent.setup();
    render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={vi.fn()} />);
    const done = screen.getByRole("button", { name: m.admin_apikey_secret_done() });
    expect(done).toBeDisabled();
    await user.click(screen.getByRole("button", { name: m.admin_apikey_secret_copy() }));
    expect(navigator.clipboard.writeText).toHaveBeenCalledWith("omck_abc123");
    expect(done).toBeEnabled();
  });
  it("ack checkbox alone enables Done (clipboard-blocked path)", async () => {
    const user = userEvent.setup();
    render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={vi.fn()} />);
    const done = screen.getByRole("button", { name: m.admin_apikey_secret_done() });
    await user.click(screen.getByRole("checkbox", { name: m.admin_apikey_secret_stored_ack() }));
    expect(done).toBeEnabled();
  });
  it("Done calls onClose", async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();
    render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={onClose} />);
    await user.click(screen.getByRole("checkbox", { name: m.admin_apikey_secret_stored_ack() }));
    await user.click(screen.getByRole("button", { name: m.admin_apikey_secret_done() }));
    expect(onClose).toHaveBeenCalled();
  });
  it("cannot be dismissed before copy or ack (no close affordance fires onClose)", () => {
    const onClose = vi.fn();
    render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={onClose} />);
    const closeBtn = screen.queryByRole("button", { name: /close/i });
    if (closeBtn) expect(closeBtn).toBeDisabled();
    else expect(closeBtn).toBeNull();
    expect(screen.getByRole("button", { name: m.admin_apikey_secret_done() })).toBeDisabled();
    expect(onClose).not.toHaveBeenCalled();
  });
  it("surfaces an error and stays locked when clipboard copy fails", async () => {
    Object.assign(navigator, {
      clipboard: { writeText: vi.fn().mockRejectedValue(new Error("denied")) },
    });
    // The current impl does not yet catch the clipboard rejection, so the
    // not-yet-handled writeText escapes as an unhandled rejection (surfaced by
    // Vitest at the Node process level). Swallow only the expected "denied"
    // error for the duration of this test so the RED lands on the missing-alert
    // assertion, not on run pollution. Once the impl adds the catch (GREEN), no
    // rejection is emitted and this listener is a no-op. `process` is not in the
    // test tsconfig's lib types, so reach it through a narrowly-typed globalThis
    // accessor rather than `any`.
    type RejectionEmitter = {
      on(event: "unhandledRejection", listener: (reason: unknown) => void): void;
      off(event: "unhandledRejection", listener: (reason: unknown) => void): void;
    };
    const proc = (globalThis as { process?: RejectionEmitter }).process;
    const swallow = (reason: unknown): void => {
      if (!(reason instanceof Error) || reason.message !== "denied") {
        throw reason;
      }
    };
    proc?.on("unhandledRejection", swallow);
    try {
      const user = userEvent.setup();
      render(<SecretRevealModal open title="New API key" secret="omck_abc123" onClose={vi.fn()} />);
      await user.click(screen.getByRole("button", { name: m.admin_apikey_secret_copy() }));
      // The persistent warning already carries role="alert"; a copy failure
      // must surface a SECOND alert (the localized copy-failed message).
      await waitFor(() => {
        expect(screen.getAllByRole("alert").length).toBeGreaterThanOrEqual(2);
      });
      expect(screen.getByRole("button", { name: m.admin_apikey_secret_done() })).toBeDisabled();
    } finally {
      proc?.off("unhandledRejection", swallow);
    }
  });
});


