import { renderHook, act, waitFor } from "@testing-library/react";
import { describe, it, expect, vi, afterEach } from "vitest";
import { useApiKeys } from "../../src/apikeys/useApiKeys";

afterEach(() => vi.restoreAllMocks());

describe("useApiKeys", () => {
  it("loads keys into ready state", async () => {
    globalThis.fetch = vi.fn(async () =>
      new Response(
        JSON.stringify({ data: { api_keys: [{ id: "k1", name: "ci" }] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    ) as unknown as typeof fetch;
    const { result } = renderHook(() => useApiKeys());
    await waitFor(() => expect(result.current.state).toBe("ready"));
    if (result.current.state === "ready") expect(result.current.keys).toHaveLength(1);
  });

  it("goes to error state on non-2xx", async () => {
    globalThis.fetch = vi.fn(async () => new Response("nope", { status: 500 })) as unknown as typeof fetch;
    const { result } = renderHook(() => useApiKeys());
    await waitFor(() => expect(result.current.state).toBe("error"));
    if (result.current.state === "error") {
      expect(result.current.message).toMatch(/listApiKeys failed/);
    }
  });

  it("starts in loading state", () => {
    // Fetch never resolves during this assertion
    let resolveFetch!: () => void;
    globalThis.fetch = vi.fn(async () => {
      await new Promise<void>((r) => { resolveFetch = r; });
      return new Response(JSON.stringify({ data: { api_keys: [] } }), { status: 200 });
    }) as unknown as typeof fetch;
    const { result } = renderHook(() => useApiKeys());
    expect(result.current.state).toBe("loading");
    resolveFetch();
  });

  it("reload() refetches and transitions back to loading then ready", async () => {
    globalThis.fetch = vi.fn(async () =>
      new Response(
        JSON.stringify({ data: { api_keys: [] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    ) as unknown as typeof fetch;
    const { result } = renderHook(() => useApiKeys());
    await waitFor(() => expect(result.current.state).toBe("ready"));

    act(() => {
      result.current.reload();
    });
    await waitFor(() => expect(result.current.state).toBe("ready"));
    // fetch should have been called twice
    expect((globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls).toHaveLength(2);
  });

  it("handles non-Error rejection gracefully (goes to error with fallback message)", async () => {
    globalThis.fetch = vi.fn(async () => {
      // Reject with a non-Error value
      return Promise.reject("string error");
    }) as unknown as typeof fetch;
    const { result } = renderHook(() => useApiKeys());
    await waitFor(() => expect(result.current.state).toBe("error"));
    if (result.current.state === "error") {
      expect(result.current.message).toBe("error");
    }
  });

  it("does not update state after unmount (mountedRef guard — lines 25-28)", async () => {
    // Create a promise we can resolve AFTER unmount to simulate
    // the in-flight request completing after the component is gone.
    let resolveAfterUnmount!: (v: Response) => void;
    globalThis.fetch = vi.fn(
      () => new Promise<Response>((r) => { resolveAfterUnmount = r; }),
    ) as unknown as typeof fetch;

    const { result, unmount } = renderHook(() => useApiKeys());
    expect(result.current.state).toBe("loading");

    // Unmount — mountedRef.current becomes false
    unmount();

    // Now resolve the fetch — the guard should silently skip the setState call
    // and NOT throw or cause "setState on unmounted component" warnings.
    resolveAfterUnmount(
      new Response(
        JSON.stringify({ data: { api_keys: [] } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    );

    // Give microtasks a chance to run — we cannot observe the final state on
    // an unmounted hook, but the test verifies no error is thrown.
    await new Promise<void>((r) => setTimeout(r, 0));
    // No assertion on result.current after unmount (would throw) — the absence
    // of an unhandled-promise-rejection or React act() warning is the signal.
  });
});



